<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeVisibilityService;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeVisibilityService $visibility,
        private readonly ThemeWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?ThemeRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Theme");
        $span = $this->startSpan("Check allow update usecase for Theme");
        try {
            $result = $this->dispatcher->dispatch(new ThemeUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?ThemeRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Theme");
        $span = $this->startSpan("Check fixed fields for update usecase for Theme");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, ThemeUpdateParams $params): ThemeUpdateResult
    {
        $this->logDebug("Run update usecase for Theme");
        $span = $this->startSpan("Run update usecase for Theme");
        try {
            $ref = new ThemeRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Theme');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ThemeUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new ThemeUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
